// Open a deck in the reference engine through its C API, run SWMMEngine::initHydrology on
// the handle (the C API handle is the SWMMEngine), then dump the engine's own context, the
// members open() sets (ctxdump::engdump) and the hydrology members initHydrology fills
// (ctxdump::hydrodump, generated by tools/ctxdump.py). initHydrology and the solver members
// are private, so SWMMEngine.hpp is read with `private`/`protected` defined as `public`
// (every standard header it reaches is included first, so only the engine's own classes
// see the change; the class layout does not depend on access). Compile with the engine's
// own defines (layout must match):
//   U=/root/work/swmm6src/upstream; B=/root/work/swmm6src/build
//   g++ -std=c++20 -O3 -ffp-contract=off -mavx2 -mfma -DNDEBUG -DSWMM_OS_LINUX \
//     -DSWMM_USE_OPENMP -fopenmp -I$U/src/engine -I$U/include -I$B/include -Igate/diff \
//     gate/diff/inithydro.cpp -o gate/diff/inithydro $B/src/engine/libopenswmm.engine.so \
//     -Wl,-rpath,$B/src/engine
// The Rust twin is crates/engine/examples/inithydro.rs.
// Usage: inithydro deck.inp [open|lenient|rdii]
//   swmm_engine_open(deck, "/dev/null", "/dev/null", NULL) (after
//   swmm_engine_set_lenient_open(e, 1) for "lenient"); when it returns 0, initHydrology().
//   "rdii" first runs rdii_.init(ctx_), as initHydraulics does before initHydrology.
//   Run from the deck's directory (relative climate files).
#include <algorithm>
#include <array>
#include <atomic>
#include <cassert>
#include <cctype>
#include <cerrno>
#include <charconv>
#include <chrono>
#include <cmath>
#include <concepts>
#include <condition_variable>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <deque>
#include <dlfcn.h>
#include <exception>
#include <filesystem>
#include <fstream>
#include <functional>
#include <future>
#include <immintrin.h>
#include <iomanip>
#include <iosfwd>
#include <iostream>
#include <istream>
#include <iterator>
#include <limits>
#include <list>
#include <locale.h>
#include <map>
#include <memory>
#include <mutex>
#include <numeric>
#include <omp.h>
#include <optional>
#include <ostream>
#include <queue>
#include <random>
#include <set>
#include <shared_mutex>
#include <span>
#include <sstream>
#include <stack>
#include <stddef.h>
#include <stdexcept>
#include <stdint.h>
#include <string>
#include <string_view>
#include <system_error>
#include <thread>
#include <tuple>
#include <type_traits>
#include <unistd.h>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <variant>
#include <vector>
#include "openswmm/engine/openswmm_engine.h"
#define private public
#define protected public
#include "core/SWMMEngine.hpp"
#undef private
#undef protected
#define CTXDUMP_ENGINE
#include "hydrodump.hpp"

int main(int argc, char** argv) {
    const char* mode = argc > 2 ? argv[2] : "open";
    SWMM_Engine e = swmm_engine_create();
    if (std::strcmp(mode, "lenient") == 0)
        swmm_engine_set_lenient_open(e, 1);
    int rc = swmm_engine_open(e, argv[1], "/dev/null", "/dev/null", nullptr);
    std::printf("open_rc %d\n", rc);
    auto* eng = static_cast<openswmm::SWMMEngine*>(e);
    if (rc == 0) {
        if (std::strcmp(mode, "rdii") == 0) {
            eng->rdii_.init(eng->ctx_);
            std::printf("initrdii\n");
        }
        eng->initHydrology();
        std::printf("inithydro\n");
    }
    ctxdump::dump(eng->context());
    ctxdump::engdump(*eng);
    ctxdump::hydrodump(*eng);
    std::fflush(stdout);
    return 0;
}
